static Json param_json(const Param& p) { Json j={{"name",p.name},{"type",type_name(p.type)},{"occurs",p.occurs}}; if(!p.required) j["occurs"]="?"; if(!p.default_value.is_null()) j["default"]=p.default_value; if(!p.enum_values.empty()) j["enum"]=p.enum_values; if(!p.description.empty())j["description"]=p.description; return j; }
Json publish_schema(const CliSpec& s) { Json ops=Json::array(); for(const auto& o:s.operations){Json ps=Json::array();for(const auto&p:o.params)ps.push_back(param_json(p));ops.push_back({{"name",o.name},{"access",o.access==Access::Read?"read":"write"},{"returns",o.returns},{"description",o.description},{"params",ps}});} return {{"schema","cli.schema.v1"},{"tool",s.tool},{"version",s.version},{"inputs",{"flags","json"}},{"globals",Json::array()},{"operations",ops}}; }
static const Operation& find_op(const CliSpec&s,const std::string& n){for(const auto&o:s.operations)if(o.name==n)return o;throw Error{ErrorCode::InvalidRequest,"unknown operation: "+n,{{"op",n}}};}
static bool value_ok(const Json&v,Type t){switch(t){case Type::String:return v.is_string();case Type::Number:return v.is_number();case Type::Integer:return v.is_number_integer();case Type::Boolean:return v.is_boolean();case Type::Object:return v.is_object();case Type::Array:return v.is_array();case Type::Json:return true;}return false;}
static Json validate(const Operation&o,const Json& raw,const std::string& form="json"){Json result=Json::object(), issues=Json::array();if(!raw.is_object())throw Error{ErrorCode::ValidationError,"input params must be an object"};for(auto it=raw.begin();it!=raw.end();++it){bool known=false;for(auto&p:o.params)known|=p.name==it.key();if(!known)issues.push_back({{"code","UNKNOWN_PARAM"},{"param",it.key()},{"message","unknown parameter: "+it.key()}});} for(const auto&p:o.params){auto it=raw.find(p.name);if(it==raw.end()){if((p.required||p.occurs=="+")&&p.default_value.is_null())issues.push_back({{"code","MISSING_REQUIRED"},{"param",p.name},{"message","missing required parameter: "+p.name}});else if(!p.default_value.is_null())result[p.name]=p.default_value;continue;}if((form=="flags"&&p.doc_only)||(form=="json"&&p.cli_only)){issues.push_back({{"code","FORM_NOT_ALLOWED"},{"param",p.name},{"message","parameter is not allowed in this input form"}});continue;}const Json&v=*it;bool multi=p.occurs=="+"||p.occurs=="*"||p.type==Type::Array;bool ok=true;Json normalized=v;if(multi){if(v.is_array())normalized=v;else normalized=Json::array({v});Type elem=p.type==Type::Array?p.item_type:p.type;for(const auto&item:normalized)if(!value_ok(item,elem))ok=false;if(p.occurs=="+"&&normalized.empty()){issues.push_back({{"code","MISSING_REQUIRED"},{"param",p.name},{"message","missing required parameter: "+p.name}});continue;}}else{ok=value_ok(v,p.type);if(p.type==Type::String&&(v.is_number()||v.is_boolean())){normalized=v.is_boolean()?(v.get<bool>()?"true":"false"):v.dump();ok=true;}}if(!ok){issues.push_back({{"code","TYPE_MISMATCH"},{"param",p.name},{"message","invalid type for parameter: "+p.name}});continue;}if(!p.enum_values.empty()){bool en=true;if(multi){for(auto&x:normalized)en&=std::find(p.enum_values.begin(),p.enum_values.end(),x)!=p.enum_values.end();}else en=std::find(p.enum_values.begin(),p.enum_values.end(),normalized)!=p.enum_values.end();if(!en){issues.push_back({{"code","ENUM_VIOLATION"},{"param",p.name},{"message","invalid enum value for parameter: "+p.name}});continue;}}result[p.name]=normalized;}if(!issues.empty())throw Error{ErrorCode::ValidationError,"invalid arguments for \""+o.name+"\"",{{"op",o.name},{"issues",issues}}};return result;}
